#!/usr/bin/env node
/**
 * BMAD Security Validation Script
 * Generated by Bastion (Security Architect) - Story 4.1
 *
 * Performs comprehensive security validation of the BMAD repository
 * Checks for credentials, vulnerabilities, and security misconfigurations
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class BMAdSecurityValidator {
    constructor() {
        this.results = {
            timestamp: new Date().toISOString(),
            vulnerabilities: [],
            warnings: [],
            passed: [],
            summary: {}
        };

        // Security patterns to detect
        this.sensitivePatterns = [
            { name: 'OpenAI API Key', pattern: /sk-[a-zA-Z0-9]{48}/, severity: 'CRITICAL' },
            { name: 'GitHub Personal Access Token', pattern: /ghp_[a-zA-Z0-9]{36}/, severity: 'CRITICAL' },
            { name: 'AWS Access Key', pattern: /AKIA[0-9A-Z]{16}/, severity: 'CRITICAL' },
            { name: 'Generic API Key', pattern: /api[_-]?key\s*[:=]\s*["'][^"']{10,}["']/, severity: 'HIGH' },
            { name: 'Password Assignment', pattern: /password\s*[:=]\s*["'][^"']+["']/, severity: 'HIGH' },
            { name: 'JWT Token', pattern: /ey[A-Za-z0-9_-]*\.[A-Za-z0-9_-]*\.[A-Za-z0-9_-]*/, severity: 'MEDIUM' },
            { name: 'SSH Private Key Header', pattern: /-----BEGIN (RSA|DSA|EC|OPENSSH) PRIVATE KEY-----/, severity: 'CRITICAL' },
            { name: 'PEM Certificate', pattern: /-----BEGIN CERTIFICATE-----/, severity: 'MEDIUM' }
        ];

        this.vulnerablePatterns = [
            { name: 'Command Injection Risk', pattern: /execSync\([^)]*\$\{[^}]+\}/, severity: 'HIGH' },
            { name: 'Eval Usage', pattern: /eval\s*\(/, severity: 'CRITICAL' },
            { name: 'Dynamic Function Creation', pattern: /new Function\s*\(/, severity: 'HIGH' },
            { name: 'Unsafe JSON Parse', pattern: /JSON\.parse\([^)]*req\./, severity: 'MEDIUM' },
            { name: 'Shell Injection Risk', pattern: /shell:\s*true/, severity: 'HIGH' }
        ];

        this.sensitiveFiles = [
            '.bmad-key',
            '.bmad-token',
            '.env',
            '.env.local',
            'id_rsa',
            'id_dsa',
            'id_ecdsa',
            'id_ed25519',
            'credentials.json',
            'service-account.json'
        ];

        this.excludePatterns = [
            /node_modules/,
            /\.git/,
            /\.DS_Store/,
            /_bmad-output/,
            /_bmad-backup/,
            /test-installation/
        ];
    }

    async validateRepository(rootPath = process.cwd()) {
        console.log('\n🔐 BMAD Security Validation Suite');
        console.log('═══════════════════════════════════════');
        console.log(`📁 Scanning: ${rootPath}`);
        console.log(`⏰ Started: ${this.results.timestamp}\n`);

        try {
            await this.scanForSensitiveFiles(rootPath);
            await this.scanForCredentials(rootPath);
            await this.scanForVulnerabilities(rootPath);
            await this.validatePermissions(rootPath);
            await this.checkGitIgnore(rootPath);

            this.generateSummary();
            this.printResults();
            await this.saveResults(rootPath);

            return this.results;
        } catch (error) {
            console.error(`❌ Security validation failed: ${error.message}`);
            throw error;
        }
    }

    async scanForSensitiveFiles(rootPath) {
        console.log('🔍 Checking for sensitive files...');
        const files = this.getFiles(rootPath);

        for (const file of files) {
            const fileName = path.basename(file);
            if (this.sensitiveFiles.some(pattern => fileName.includes(pattern))) {
                // Check if file exists and is not empty
                try {
                    const stats = fs.statSync(file);
                    if (stats.size > 0) {
                        this.results.vulnerabilities.push({
                            type: 'SENSITIVE_FILE',
                            severity: 'CRITICAL',
                            file: file,
                            message: `Sensitive file present: ${fileName}`,
                            recommendation: 'Remove or secure this file'
                        });
                    }
                } catch (error) {
                    // File doesn't exist, which is good
                }
            }
        }
    }

    async scanForCredentials(rootPath) {
        console.log('🔐 Scanning for hardcoded credentials...');
        const files = this.getFiles(rootPath, ['.js', '.ts', '.py', '.yaml', '.yml', '.json', '.md']);

        for (const file of files) {
            try {
                const content = fs.readFileSync(file, 'utf8');
                const lines = content.split('\n');

                lines.forEach((line, lineNumber) => {
                    this.sensitivePatterns.forEach(pattern => {
                        const matches = line.match(pattern.pattern);
                        if (matches) {
                            // Skip documentation examples and comments
                            if (this.isDocumentationExample(line, file)) {
                                return;
                            }

                            this.results.vulnerabilities.push({
                                type: 'CREDENTIAL_EXPOSURE',
                                severity: pattern.severity,
                                file: file,
                                line: lineNumber + 1,
                                pattern: pattern.name,
                                match: matches[0],
                                message: `Potential ${pattern.name} found`,
                                recommendation: 'Use environment variables or secure key management'
                            });
                        }
                    });
                });
            } catch (error) {
                // Skip files that can't be read
                continue;
            }
        }
    }

    async scanForVulnerabilities(rootPath) {
        console.log('🐛 Scanning for security vulnerabilities...');
        const files = this.getFiles(rootPath, ['.js', '.ts', '.py']);

        for (const file of files) {
            try {
                const content = fs.readFileSync(file, 'utf8');
                const lines = content.split('\n');

                lines.forEach((line, lineNumber) => {
                    this.vulnerablePatterns.forEach(pattern => {
                        const matches = line.match(pattern.pattern);
                        if (matches) {
                            this.results.vulnerabilities.push({
                                type: 'SECURITY_VULNERABILITY',
                                severity: pattern.severity,
                                file: file,
                                line: lineNumber + 1,
                                pattern: pattern.name,
                                match: matches[0],
                                message: `Security vulnerability: ${pattern.name}`,
                                recommendation: 'Review and implement secure alternatives'
                            });
                        }
                    });
                });
            } catch (error) {
                continue;
            }
        }
    }

    async validatePermissions(rootPath) {
        console.log('🔒 Checking file permissions...');
        const sensitiveFileChecks = [
            { path: '.bmad-key', expectedMode: '0600' },
            { path: '.bmad-token', expectedMode: '0600' },
            { path: '.env', expectedMode: '0600' },
            { path: 'package.json', expectedMode: '0644' }
        ];

        for (const check of sensitiveFileChecks) {
            const filePath = path.join(rootPath, check.path);
            if (fs.existsSync(filePath)) {
                try {
                    const stats = fs.statSync(filePath);
                    const currentMode = (stats.mode & parseInt('777', 8)).toString(8);

                    if (currentMode !== check.expectedMode.replace('0', '')) {
                        this.results.warnings.push({
                            type: 'PERMISSION_WARNING',
                            severity: 'MEDIUM',
                            file: filePath,
                            message: `File permissions may be too permissive: ${currentMode}`,
                            expected: check.expectedMode,
                            recommendation: `Consider setting permissions to ${check.expectedMode}`
                        });
                    } else {
                        this.results.passed.push({
                            type: 'PERMISSION_CHECK',
                            file: filePath,
                            message: `Correct permissions: ${check.expectedMode}`
                        });
                    }
                } catch (error) {
                    // Permission check failed
                }
            }
        }
    }

    async checkGitIgnore(rootPath) {
        console.log('📋 Validating .gitignore configuration...');
        const gitignorePath = path.join(rootPath, '.gitignore');

        if (!fs.existsSync(gitignorePath)) {
            this.results.vulnerabilities.push({
                type: 'CONFIGURATION_ERROR',
                severity: 'HIGH',
                file: gitignorePath,
                message: '.gitignore file not found',
                recommendation: 'Create .gitignore to prevent sensitive file commits'
            });
            return;
        }

        const gitignoreContent = fs.readFileSync(gitignorePath, 'utf8');
        const requiredPatterns = [
            '.bmad-key',
            '.bmad-token',
            '.env',
            '.env.local',
            '*.env',
            'node_modules/',
            '.DS_Store'
        ];

        const missingPatterns = requiredPatterns.filter(pattern =>
            !gitignoreContent.includes(pattern)
        );

        if (missingPatterns.length > 0) {
            this.results.warnings.push({
                type: 'GITIGNORE_WARNING',
                severity: 'MEDIUM',
                file: gitignorePath,
                message: `Missing .gitignore patterns: ${missingPatterns.join(', ')}`,
                recommendation: 'Add missing patterns to prevent sensitive file commits'
            });
        } else {
            this.results.passed.push({
                type: 'GITIGNORE_CHECK',
                file: gitignorePath,
                message: 'All required patterns present in .gitignore'
            });
        }
    }

    isDocumentationExample(line, file) {
        // Skip documentation files and examples
        if (file.includes('/docs/') || file.includes('/examples/') || file.includes('README') || file.includes('.md')) {
            return true;
        }

        // Skip commented lines
        if (line.trim().startsWith('//') || line.trim().startsWith('#') || line.trim().startsWith('*')) {
            return true;
        }

        // Skip obvious examples
        if (line.includes('example') || line.includes('EXAMPLE') || line.includes('your-api-key') ||
            line.includes('xxxxxxxxxxxx') || line.includes('sk-...') || line.includes('ghp_xxx')) {
            return true;
        }

        return false;
    }

    getFiles(dir, extensions = []) {
        let files = [];

        try {
            const items = fs.readdirSync(dir);

            for (const item of items) {
                const fullPath = path.join(dir, item);

                // Skip excluded patterns
                if (this.excludePatterns.some(pattern => pattern.test(fullPath))) {
                    continue;
                }

                try {
                    const stats = fs.statSync(fullPath);

                    if (stats.isDirectory()) {
                        files = files.concat(this.getFiles(fullPath, extensions));
                    } else if (extensions.length === 0 || extensions.some(ext => fullPath.endsWith(ext))) {
                        files.push(fullPath);
                    }
                } catch (error) {
                    continue;
                }
            }
        } catch (error) {
            // Directory access failed
        }

        return files;
    }

    generateSummary() {
        const critical = this.results.vulnerabilities.filter(v => v.severity === 'CRITICAL').length;
        const high = this.results.vulnerabilities.filter(v => v.severity === 'HIGH').length;
        const medium = this.results.vulnerabilities.filter(v => v.severity === 'MEDIUM').length;
        const low = this.results.vulnerabilities.filter(v => v.severity === 'LOW').length;

        this.results.summary = {
            total_vulnerabilities: this.results.vulnerabilities.length,
            critical: critical,
            high: high,
            medium: medium,
            low: low,
            warnings: this.results.warnings.length,
            passed_checks: this.results.passed.length,
            security_score: this.calculateSecurityScore()
        };
    }

    calculateSecurityScore() {
        const critical = this.results.vulnerabilities.filter(v => v.severity === 'CRITICAL').length;
        const high = this.results.vulnerabilities.filter(v => v.severity === 'HIGH').length;
        const medium = this.results.vulnerabilities.filter(v => v.severity === 'MEDIUM').length;

        // Start with perfect score
        let score = 100;

        // Deduct points based on severity
        score -= (critical * 25);  // Critical: -25 points each
        score -= (high * 15);      // High: -15 points each
        score -= (medium * 5);     // Medium: -5 points each

        return Math.max(0, score);
    }

    printResults() {
        console.log('\n📊 SECURITY VALIDATION RESULTS');
        console.log('═══════════════════════════════════════');

        // Summary
        const summary = this.results.summary;
        console.log(`🎯 Security Score: ${summary.security_score}/100`);
        console.log(`⚠️  Total Issues: ${summary.total_vulnerabilities}`);
        console.log(`🔴 Critical: ${summary.critical}`);
        console.log(`🟠 High: ${summary.high}`);
        console.log(`🟡 Medium: ${summary.medium}`);
        console.log(`🔵 Low: ${summary.low}`);
        console.log(`⚪ Warnings: ${summary.warnings}`);
        console.log(`✅ Passed: ${summary.passed_checks}`);

        // Detailed results
        if (this.results.vulnerabilities.length > 0) {
            console.log('\\n❌ VULNERABILITIES FOUND:');
            console.log('─'.repeat(50));

            this.results.vulnerabilities.forEach((vuln, index) => {
                const severityIcon = this.getSeverityIcon(vuln.severity);
                console.log(`\\n${index + 1}. ${severityIcon} ${vuln.severity}: ${vuln.message}`);
                console.log(`   📁 File: ${vuln.file}`);
                if (vuln.line) console.log(`   📍 Line: ${vuln.line}`);
                if (vuln.pattern) console.log(`   🔍 Pattern: ${vuln.pattern}`);
                if (vuln.match) console.log(`   🎯 Match: ${vuln.match}`);
                console.log(`   💡 Recommendation: ${vuln.recommendation}`);
            });
        }

        if (this.results.warnings.length > 0) {
            console.log('\\n⚠️  WARNINGS:');
            console.log('─'.repeat(50));

            this.results.warnings.forEach((warning, index) => {
                console.log(`\\n${index + 1}. ${warning.message}`);
                console.log(`   📁 File: ${warning.file}`);
                console.log(`   💡 Recommendation: ${warning.recommendation}`);
            });
        }

        console.log('\\n═══════════════════════════════════════');

        if (summary.security_score >= 90) {
            console.log('🎉 EXCELLENT: Security posture is strong');
        } else if (summary.security_score >= 70) {
            console.log('✅ GOOD: Minor security improvements needed');
        } else if (summary.security_score >= 50) {
            console.log('⚠️  WARNING: Multiple security issues detected');
        } else {
            console.log('🚨 CRITICAL: Immediate security attention required');
        }
    }

    getSeverityIcon(severity) {
        switch (severity) {
            case 'CRITICAL': return '🔴';
            case 'HIGH': return '🟠';
            case 'MEDIUM': return '🟡';
            case 'LOW': return '🔵';
            default: return '⚪';
        }
    }

    async saveResults(rootPath) {
        const resultsPath = path.join(rootPath, 'docs/testing/security/security-validation-results.json');

        try {
            fs.writeFileSync(resultsPath, JSON.stringify(this.results, null, 2));
            console.log(`\\n💾 Results saved to: ${resultsPath}`);
        } catch (error) {
            console.error(`❌ Failed to save results: ${error.message}`);
        }
    }
}

// Run validation if called directly
if (require.main === module) {
    const validator = new BMAdSecurityValidator();
    validator.validateRepository()
        .then(results => {
            process.exit(results.summary.critical > 0 || results.summary.high > 0 ? 1 : 0);
        })
        .catch(error => {
            console.error('Validation failed:', error);
            process.exit(1);
        });
}

module.exports = { BMAdSecurityValidator };